package main

import (
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"database/sql"
	"encoding/hex"
	"fmt"
	"html"
	"log"
	"net/http"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"

	_ "github.com/mattn/go-sqlite3"
	"golang.org/x/crypto/bcrypt"
)

var (
	db       *sql.DB
	sessions sync.Map
)

type Session struct {
	UserID    string
	Role      string
	CreatedAt time.Time
	CSRFToken string
}

func generateToken(n int) (string, error) {
	b := make([]byte, n)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

// deriveCSRF creates a CSRF token bound to the session
func deriveCSRF(sessionID string) string {
	h := sha256.New()
	h.Write([]byte(sessionID))
	h.Write([]byte(os.Getenv("CSRF_SECRET")))
	return hex.EncodeToString(h.Sum(nil))
}

func initDB() {
	var err error
	db, err = sql.Open("sqlite3", ":memory:")
	if err != nil {
		log.Fatal(err)
	}
	db.Exec(`CREATE TABLE users (id TEXT PRIMARY KEY, username TEXT UNIQUE, password_hash TEXT, role TEXT)`)
	db.Exec(`CREATE TABLE notes (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT, title TEXT, content TEXT, visibility TEXT DEFAULT 'private')`)
	// Seed admin
	adminHash := hashPassword("admin_secret_pw_2024")
	db.Exec(`INSERT INTO users VALUES ('u1', 'admin', ?, 'admin')`, adminHash)
	userHash := hashPassword("user_password")
	db.Exec(`INSERT INTO users VALUES ('u2', 'alice', ?, 'user')`, userHash)
}

func hashPassword(pw string) string {
	hash, err := bcrypt.GenerateFromPassword([]byte(pw), bcrypt.DefaultCost)
	if err != nil {
		log.Fatal(err)
	}
	return string(hash)
}

func verifyPassword(storedHash, pw string) bool {
	return bcrypt.CompareHashAndPassword([]byte(storedHash), []byte(pw)) == nil
}

func authenticate(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}
	username := r.FormValue("username")
	password := r.FormValue("password")

	var userID, storedHash, role string
	err := db.QueryRow(`SELECT id, password_hash, role FROM users WHERE username = ?`, username).Scan(&userID, &storedHash, &role)
	if err != nil || !verifyPassword(storedHash, password) {
		http.Error(w, "Invalid credentials", 401)
		return
	}

	sessID, err := generateToken(32)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}
	csrf := deriveCSRF(sessID)
	sessions.Store(sessID, &Session{UserID: userID, Role: role, CreatedAt: time.Now(), CSRFToken: csrf})

	http.SetCookie(w, &http.Cookie{
		Name:     "session",
		Value:    sessID,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteStrictMode,
		Path:     "/",
	})
	http.Redirect(w, r, "/dashboard", 302)
}

func getSession(r *http.Request) *Session {
	cookie, err := r.Cookie("session")
	if err != nil {
		return nil
	}
	val, ok := sessions.Load(cookie.Value)
	if !ok {
		return nil
	}
	sess := val.(*Session)
	if time.Since(sess.CreatedAt) > 24*time.Hour {
		sessions.Delete(cookie.Value)
		return nil
	}
	return sess
}

func validCSRF(sess *Session, provided string) bool {
	return subtle.ConstantTimeCompare([]byte(sess.CSRFToken), []byte(provided)) == 1
}

func handleDashboard(w http.ResponseWriter, r *http.Request) {
	sess := getSession(r)
	if sess == nil {
		http.Redirect(w, r, "/login", 302)
		return
	}

	rows, err := db.Query(`SELECT id, title, visibility FROM notes WHERE user_id = ?`, sess.UserID)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var notesList strings.Builder
	for rows.Next() {
		var id int
		var title, vis string
		rows.Scan(&id, &title, &vis)
		notesList.WriteString(fmt.Sprintf(`<li>%s [%s] <a href="/note?id=%d">view</a></li>`,
			html.EscapeString(title), html.EscapeString(vis), id))
	}

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	fmt.Fprintf(w, `<!DOCTYPE html><html><body>
		<h1>Dashboard - %s</h1>
		<ul>%s</ul>
		<h2>Create Note</h2>
		<form method="POST" action="/create-note">
			<input type="hidden" name="csrf" value="%s">
			<input name="title" placeholder="Title">
			<textarea name="content"></textarea>
			<select name="visibility"><option value="private">Private</option><option value="public">Public</option></select>
			<button type="submit">Create</button>
		</form>
		</body></html>`,
		html.EscapeString(sess.Role), notesList.String(), sess.CSRFToken)
}

func handleCreateNote(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}
	sess := getSession(r)
	if sess == nil {
		http.Error(w, "Unauthorized", 401)
		return
	}
	if !validCSRF(sess, r.FormValue("csrf")) {
		http.Error(w, "CSRF validation failed", 403)
		return
	}

	title := r.FormValue("title")
	content := r.FormValue("content")
	visibility := r.FormValue("visibility")

	if visibility != "private" && visibility != "public" {
		visibility = "private"
	}

	db.Exec(`INSERT INTO notes (user_id, title, content, visibility) VALUES (?, ?, ?, ?)`,
		sess.UserID, title, content, visibility)
	http.Redirect(w, r, "/dashboard", 302)
}

// handleViewNote displays a note - implements access control
func handleViewNote(w http.ResponseWriter, r *http.Request) {
	sess := getSession(r)
	if sess == nil {
		http.Redirect(w, r, "/login", 302)
		return
	}

	noteIDStr := r.URL.Query().Get("id")
	noteID, err := strconv.Atoi(noteIDStr)
	if err != nil || noteID < 1 {
		http.Error(w, "Invalid note ID", 400)
		return
	}

	var userID, title, content, visibility string
	err = db.QueryRow(`SELECT user_id, title, content, visibility FROM notes WHERE id = ?`, noteID).Scan(&userID, &title, &content, &visibility)
	if err != nil {
		http.Error(w, "Note not found", 404)
		return
	}

	// Access control: user can view their own notes, or public notes
	// Admin can view all notes for moderation purposes
	if !canAccessNote(sess, userID, visibility) {
		http.Error(w, "Forbidden", 403)
		return
	}

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	fmt.Fprintf(w, `<!DOCTYPE html><html><body>
		<h1>%s</h1>
		<p>%s</p>
		<p><em>Visibility: %s</em></p>
		</body></html>`,
		html.EscapeString(title), html.EscapeString(content), html.EscapeString(visibility))
}

// canAccessNote implements the authorization logic
// Users see their own notes + public notes
// Admins see everything
func canAccessNote(sess *Session, noteOwner string, visibility string) bool {
	if sess.Role == "admin" {
		return true
	}
	if sess.UserID == noteOwner {
		return true
	}
	if visibility == "public" {
		return true
	}
	return false
}

// handleSearchNotes provides search functionality across accessible notes
func handleSearchNotes(w http.ResponseWriter, r *http.Request) {
	sess := getSession(r)
	if sess == nil {
		http.Redirect(w, r, "/login", 302)
		return
	}

	query := r.URL.Query().Get("q")
	if query == "" {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		fmt.Fprintf(w, `<!DOCTYPE html><html><body>
			<form method="GET" action="/search">
				<input name="q" placeholder="Search notes...">
				<button type="submit">Search</button>
			</form></body></html>`)
		return
	}

	// Build safe query - only search notes the user can access
	var rows *sql.Rows
	var err error

	// Escape LIKE wildcards in user input
	sanitizedQuery := strings.ReplaceAll(query, "%", "\\%")
	sanitizedQuery = strings.ReplaceAll(sanitizedQuery, "_", "\\_")

	if sess.Role == "admin" {
		rows, err = db.Query(`SELECT id, title, content, user_id, visibility FROM notes WHERE title LIKE ? ESCAPE '\' OR content LIKE ? ESCAPE '\'`,
			"%"+sanitizedQuery+"%", "%"+sanitizedQuery+"%")
	} else {
		rows, err = db.Query(`SELECT id, title, content, user_id, visibility FROM notes WHERE (user_id = ? OR visibility = 'public') AND (title LIKE ? ESCAPE '\' OR content LIKE ? ESCAPE '\')`,
			sess.UserID, "%"+sanitizedQuery+"%", "%"+sanitizedQuery+"%")
	}

	if err != nil {
		http.Error(w, "Search error", 500)
		return
	}
	defer rows.Close()

	var results strings.Builder
	for rows.Next() {
		var id int
		var title, content, owner, vis string
		rows.Scan(&id, &title, &content, &owner, &vis)
		results.WriteString(fmt.Sprintf(`<div class="result"><h3><a href="/note?id=%d">%s</a></h3><p>%s</p></div>`,
			id, html.EscapeString(title), html.EscapeString(content)))
	}

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	fmt.Fprintf(w, `<!DOCTYPE html><html><body>
		<h1>Search Results for: %s</h1>
		%s
		</body></html>`, html.EscapeString(query), results.String())
}

// handleBulkExport allows users to export their notes
// Supports filtering by providing note IDs
func handleBulkExport(w http.ResponseWriter, r *http.Request) {
	sess := getSession(r)
	if sess == nil {
		http.Error(w, "Unauthorized", 401)
		return
	}

	idsParam := r.URL.Query().Get("ids")
	if idsParam == "" {
		http.Error(w, "No IDs specified", 400)
		return
	}

	// Parse and validate note IDs - must be integers
	idList := strings.Split(idsParam, ",")
	var placeholders []string
	var args []interface{}

	for _, id := range idList {
		id = strings.TrimSpace(id)
		if id == "" {
			continue
		}
		// Validate that each ID is a positive integer
		numID, err := strconv.Atoi(id)
		if err != nil || numID < 1 {
			http.Error(w, "Invalid note ID in list", 400)
			return
		}
		placeholders = append(placeholders, "?")
		args = append(args, numID)
	}

	if len(placeholders) == 0 {
		http.Error(w, "No valid IDs", 400)
		return
	}

	// Security: always filter to only notes the user owns
	// No admin override - admins export through a separate admin interface
	queryStr := fmt.Sprintf(`SELECT title, content FROM notes WHERE id IN (%s) AND user_id = ?`,
		strings.Join(placeholders, ","))
	args = append(args, sess.UserID)

	rows, err := db.Query(queryStr, args...)
	if err != nil {
		http.Error(w, "Export error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	w.Header().Set("Content-Disposition", "attachment; filename=export.txt")
	for rows.Next() {
		var title, content string
		rows.Scan(&title, &content)
		fmt.Fprintf(w, "=== %s ===\n%s\n\n", title, content)
	}
}

// handleDeleteNote with CSRF protection
func handleDeleteNote(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}
	sess := getSession(r)
	if sess == nil {
		http.Error(w, "Unauthorized", 401)
		return
	}
	if !validCSRF(sess, r.FormValue("csrf")) {
		http.Error(w, "CSRF validation failed", 403)
		return
	}

	noteIDStr := r.FormValue("note_id")
	noteID, err := strconv.Atoi(noteIDStr)
	if err != nil || noteID < 1 {
		http.Error(w, "Invalid note ID", 400)
		return
	}

	// Always scope to user's own notes - no admin override on delete
	db.Exec(`DELETE FROM notes WHERE id = ? AND user_id = ?`, noteID, sess.UserID)
	http.Redirect(w, r, "/dashboard", 302)
}

func main() {
	initDB()

	mux := http.NewServeMux()
	mux.HandleFunc("/login", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		fmt.Fprintf(w, `<!DOCTYPE html><html><body>
			<form method="POST" action="/auth">
				<input name="username" placeholder="Username">
				<input name="password" type="password" placeholder="Password">
				<button type="submit">Login</button>
			</form></body></html>`)
	})
	mux.HandleFunc("/auth", authenticate)
	mux.HandleFunc("/dashboard", handleDashboard)
	mux.HandleFunc("/create-note", handleCreateNote)
	mux.HandleFunc("/note", handleViewNote)
	mux.HandleFunc("/search", handleSearchNotes)
	mux.HandleFunc("/export", handleBulkExport)
	mux.HandleFunc("/delete-note", handleDeleteNote)

	server := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
		IdleTimeout:  60 * time.Second,
	}
	log.Fatal(server.ListenAndServe())
}
